<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campus Connect</title><style>
:root{--navy:#1e3a5f;--blue:#2563eb;--ink:#0f172a;--muted:#64748b;--line:#cbd5e1;--bg:#f8fafc;--card:#fff;--amber:#a16207}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 Arial,sans-serif}.shell{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{background:var(--navy);color:#fff;padding:28px 18px}.brand{font:700 25px Georgia,serif;margin:0 8px 38px}.brand small{display:block;color:#bfdbfe;font:12px Arial;letter-spacing:.12em;text-transform:uppercase;margin-top:3px}.nav a{display:block;color:#dbeafe;text-decoration:none;padding:12px 14px;border-radius:7px;margin:4px 0}.nav a:hover,.nav a.active{background:#31557f;color:#fff}.main{padding:32px;max-width:1500px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:28px}.eyebrow{color:var(--muted);margin:0;font-size:14px}.top h1{font:700 30px Georgia,serif;margin:2px 0}.user{font-size:14px;color:var(--muted)}button,.button{border:0;background:var(--blue);color:#fff;border-radius:6px;padding:10px 15px;font-weight:700;text-decoration:none;cursor:pointer}button:hover,.button:hover{filter:brightness(.91)}button:focus,a:focus,input:focus,select:focus,textarea:focus{outline:3px solid #93c5fd;outline-offset:2px}.logout{background:transparent;color:#dbeafe;padding:12px 14px;font-weight:400}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:9px;padding:20px}.metric{font:700 32px Georgia,serif;margin:8px 0 0}.label{font-size:13px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}.wide{margin-top:24px}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse}.table th{text-align:left;font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}.table th,.table td{padding:13px 10px;border-bottom:1px solid #e5e7eb}.ticket{color:var(--blue);font-weight:bold;text-decoration:none}.badge{font-size:12px;font-weight:bold;padding:4px 8px;border-radius:99px;background:#e0e7ff;color:#3730a3}.pendiente{background:#fef3c7;color:#92400e}.en_proceso{background:#dbeafe;color:#1d4ed8}.resuelta,.cerrada{background:#dcfce7;color:#166534}.alta,.critica{background:#fee2e2;color:#991b1b}.filters,.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;align-items:end;margin-bottom:18px}label{font-weight:700;font-size:14px;display:block}input,select,textarea{width:100%;border:1px solid var(--line);border-radius:6px;padding:10px;margin-top:5px;background:white;font:inherit}.detail{display:grid;grid-template-columns:2fr 1fr;gap:22px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:14px}.comment{border-left:3px solid #93c5fd;padding:8px 12px;margin:12px 0;background:#f8fafc}.flash{padding:12px 16px;background:#dcfce7;color:#166534;border-radius:6px;margin:0 0 18px}.error{padding:12px;background:#fee2e2;color:#991b1b;border-radius:6px;margin-bottom:15px}.login{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#1e3a5f,#0f2743)}.login .card{width:min(420px,92vw);padding:34px}.login h1{font:700 30px Georgia,serif;margin-top:0}.muted{color:var(--muted)}@media(max-width:900px){.shell{grid-template-columns:1fr}.side{padding:16px}.brand{margin-bottom:12px}.nav{display:flex;gap:4px;overflow:auto}.nav a{white-space:nowrap}.grid{grid-template-columns:repeat(2,1fr)}.detail{grid-template-columns:1fr}.main{padding:22px}.filters,.form-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.grid,.filters,.form-grid,.meta{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}.main{padding:16px}}
</style></head><body><div class="shell"><aside class="side"><p class="brand">Campus Connect<small>Administración</small></p><nav class="nav"><a href="{{route('dashboard')}}">Resumen</a><a href="{{route('tickets.index')}}">Solicitudes</a><a href="{{route('reports')}}">Reportes</a><form method="POST" action="{{route('logout')}}">@csrf<button class="logout">Cerrar sesión</button></form></nav></aside><main class="main"><header class="top"><div><p class="eyebrow">Gestión institucional</p><h1>@yield('title')</h1></div><span class="user">{{auth()->user()->name}}</span></header>@if(session('success'))<div class="flash">{{session('success')}}</div>@endif @yield('content')</main></div></body></html>
